// UpdateOrg changes an organization with f, which may refuse with an error.
func (s *Store) UpdateOrg(id string, f func(*Org) error) (Org, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[id]
	if !ok {
		return Org{}, ErrNotFound
	}
	if err := f(&o); err != nil {
		return Org{}, err
	}
	o.ID = id
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	s.orgs[id] = o
	return o, nil
}

args.new_string:
// UpdateOrg changes an organization with f, which may refuse with an error. A new plan must have a seat limit at or above
// the seats in use: otherwise it is refused with an OverSeatLimitError.
func (s *Store) UpdateOrg(id string, f func(*Org) error) (Org, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.orgs[id]
	if !ok {
		return Org{}, ErrNotFound
	}
	o := old
	if err := f(&o); err != nil {
		return Org{}, err
	}
	o.ID = id
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	if limit, limited := o.Plan.SeatLimit(); limited && o.Plan != old.Plan {
		if used := s.seatsUsedLocked(id); used > limit {
			return Org{}, &OverSeatLimitError{Limit: limit, Used: used}
		}
	}
	s.orgs[id] = o
	return o, nil
}

