func (s *Store) SetMemberRole(orgID, userID string, role Role) (Member, error) {
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return Member{}, ErrNotFound
	}
	if m.Role == RoleViewer && role != RoleViewer {
		if err := s.needSeatLocked(orgID); err != nil {
			return Member{}, err
		}
	}
	m.Role = role

