package store

import (
	"errors"
	"sync"
	"testing"
)

func TestSeatLimitsOfPlans(t *testing.T) {
	for _, c := range []struct {
		plan    OrgPlan
		limit   int
		limited bool
	}{{OrgFree, 3, true}, {OrgTeam, 10, true}, {OrgBusiness, 0, false}} {
		if limit, limited := c.plan.SeatLimit(); limit != c.limit || limited != c.limited {
			t.Errorf("%s: SeatLimit = %d, %v", c.plan, limit, limited)
		}
	}
}

func TestSeatsCountMembersAndPendingInvites(t *testing.T) {
	s := New()
	o, _ := s.CreateOrg("Free Co", OrgFree, "UTC", 0, t0)
	owner, _ := s.CreateUser("owner@free.example", "Owner", t0)
	_, _ = s.AddMember(o.ID, owner.ID, RoleOwner, t0)
	v, _ := s.CreateUser("viewer@free.example", "Viewer", t0)
	_, _ = s.AddMember(o.ID, v.ID, RoleViewer, t0)
	if got := s.Seats(o.ID); got.Used != 1 || got.Limit == nil || *got.Limit != 3 {
		t.Fatalf("Seats = %+v, want 1 of 3 (the viewer is free)", got)
	}
	inv, _ := s.CreateInvite(o.ID, "a@free.example", RoleMember, owner.ID, t0)
	if _, err := s.CreateInvite(o.ID, "b@free.example", RoleViewer, owner.ID, t0); err != nil {
		t.Fatalf("a viewer invite took a seat: %v", err)
	}
	if got := s.Seats(o.ID); got.Used != 2 {
		t.Fatalf("Seats = %+v, want 2 (a pending member invite holds a seat)", got)
	}
	if _, err := s.RevokeInvite(o.ID, inv.ID, t0); err != nil {
		t.Fatal(err)
	}
	if got := s.Seats(o.ID); got.Used != 1 {
		t.Fatalf("Seats = %+v after revoking, want 1", got)
	}
}

func TestInviteNeedsASeat(t *testing.T) {
	s := New()
	o, _ := s.CreateOrg("Free Co", OrgFree, "UTC", 0, t0)
	owner, _ := s.CreateUser("owner@free.example", "Owner", t0)
	_, _ = s.AddMember(o.ID, owner.ID, RoleOwner, t0)
	for _, e := range []string{"a@free.example", "b@free.example"} {
		if _, err := s.CreateInvite(o.ID, e, RoleMember, owner.ID, t0); err != nil {
			t.Fatal(err)
