package api_test

import (
	"fmt"
	"net/http"
	"reflect"
	"sync"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

// orgSeats is what GET /v1/org shows about the plan and the seats.
type orgSeats struct {
	Plan  string `json:"plan"`
	Seats struct {
		Used  int  `json:"used"`
		Limit *int `json:"limit"`
	} `json:"seats"`
}

func getSeats(t *testing.T, e *apitest.Env, key string) orgSeats {
	t.Helper()
	var o orgSeats
	e.MustDo(http.StatusOK, "GET", "/v1/org", key, nil, &o)
	return o
}

// wantBody checks the response's status and its exact JSON body.
func wantBody(t *testing.T, r *apitest.Response, status int, want map[string]any) {
	t.Helper()
	if r.Code != status {
		t.Fatalf("status: %s, want %d", r, status)
	}
	if got := r.Map(t); !reflect.DeepEqual(got, want) {
		t.Fatalf("body = %v, want %v", got, want)
	}
}

func TestSeatLimits(t *testing.T) {
	e := apitest.New(t)

	// Acme is a team organization (10 seats); its owner is one seat.
	if o := getSeats(t, e, e.Acme.Key); o.Seats.Used != 1 || o.Seats.Limit == nil || *o.Seats.Limit != 10 {
		t.Fatalf("seats = %+v", o.Seats)
	}
	var invites []store.Invite
	for _, email := range []string{"a@people.example", "b@people.example", "c@people.example"} {
		var inv store.Invite
		e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": email, "role": "member"}, &inv)
		invites = append(invites, inv)
	}
	if o := getSeats(t, e, e.Acme.Key); o.Seats.Used != 4 {
		t.Fatalf("seats after three invites = %+v", o.Seats)
	}

	// Four seats do not fit on the free plan: the change is refused and nothing changes.
	wantBody(t, e.Do("PATCH", "/v1/org", e.Acme.Key, map[string]string{"plan": "free"}), http.StatusConflict,
		map[string]any{"error": "over_seat_limit", "limit": 3.0, "used": 4.0})
	if o := getSeats(t, e, e.Acme.Key); o.Plan != "team" || o.Seats.Used != 4 {
		t.Fatalf("after the refused change: %+v", o)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/invites/"+invites[2].ID, e.Acme.Key, nil, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/org", e.Acme.Key, map[string]string{"plan": "free"}, nil)
	if o := getSeats(t, e, e.Acme.Key); o.Plan != "free" || o.Seats.Used != 3 || o.Seats.Limit == nil || *o.Seats.Limit != 3 {
		t.Fatalf("seats on the free plan = %+v", o)
	}

	// Full: a new invite for a seat is refused, a viewer's is not.
	wantBody(t, e.Do("POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "d@people.example", "role": "member"}), http.StatusPaymentRequired,
		map[string]any{"error": "seat_limit_reached", "limit": 3.0, "used": 3.0})
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "v@people.example", "role": "viewer"}, nil)

	// Accepting an invite holds no new seat: the invite's seat becomes the member's.
	var accepted struct {
		Member store.Member `json:"member"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invites/accept", "", map[string]string{"token": invites[0].Token, "name": "A"}, &accepted)
	if o := getSeats(t, e, e.Acme.Key); o.Seats.Used != 3 {
		t.Fatalf("seats after accepting = %+v", o.Seats)
	}

	// A viewer who becomes a member needs a free seat.
	viewer, viewerKey := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	wantBody(t, e.Do("PATCH", "/v1/members/"+viewer.ID, e.Acme.Key, map[string]string{"role": "member"}), http.StatusPaymentRequired,
		map[string]any{"error": "seat_limit_reached", "limit": 3.0, "used": 3.0})
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/invites/"+invites[1].ID, e.Acme.Key, nil, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+viewer.ID, e.Acme.Key, map[string]string{"role": "member"}, nil)
	if o := getSeats(t, e, viewerKey); o.Seats.Used != 3 {
		t.Fatalf("seats after the viewer became a member = %+v", o.Seats)
	}

	// The business plan is unlimited: the limit is null.
	e.MustDo(http.StatusOK, "PATCH", "/v1/org", e.Acme.Key, map[string]string{"plan": "business"}, nil)
	if o := getSeats(t, e, e.Acme.Key); o.Seats.Limit != nil || o.Seats.Used != 3 {
		t.Fatalf("seats on business = %+v", o.Seats)
	}
}

