package store

import "fmt"

// SeatLimit is how many seats a plan allows, and whether it allows a limited number at all. Viewers are free: a seat is
// taken by a member whose role is not viewer, and by a pending invite whose role is not viewer.
func (p OrgPlan) SeatLimit() (limit int, limited bool) {
	switch p {
	case OrgFree:
		return 3, true
	case OrgTeam:
		return 10, true
	}
	return 0, false
}

// SeatLimitError says a change would need a seat that the organization's plan does not have.
type SeatLimitError struct{ Limit, Used int }

func (e *SeatLimitError) Error() string {
	return fmt.Sprintf("the plan allows %d seats and %d are in use", e.Limit, e.Used)
}

// OverSeatLimitError says a plan change would leave the organization with more seats in use than the new plan allows.
type OverSeatLimitError struct{ Limit, Used int }

func (e *OverSeatLimitError) Error() string {
	return fmt.Sprintf("the plan allows %d seats and %d are in use", e.Limit, e.Used)
}

// Seats is an organization's seat use against its plan. Limit is nil when the plan is unlimited.
type Seats struct {
	Used  int
	Limit *int
}

// Seats returns an organization's seat use.
func (s *Store) Seats(orgID string) Seats {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.seatsLocked(orgID)
}

func (s *Store) seatsLocked(orgID string) Seats {
	out := Seats{Used: s.seatsUsedLocked(orgID)}
	if limit, limited := s.orgs[orgID].Plan.SeatLimit(); limited {
		out.Limit = &limit
	}
	return out
}

// seatsUsedLocked counts the seats in use by an organization's members and pending invites. The caller holds s.mu.
func (s *Store) seatsUsedLocked(orgID string) int {
	used := 0
	for _, m := range s.members {
		if m.OrgID == orgID && m.Role != RoleViewer {
			used++
		}
	}
	for _, inv := range s.invites {
		if inv.OrgID == orgID && inv.Role != RoleViewer && inv.AcceptedAt == nil && inv.RevokedAt == nil {
			used++
		}
	}
	return used
}

// needSeatLocked returns a SeatLimitError when the organization has no free seat for one more. The caller holds s.mu.
func (s *Store) needSeatLocked(orgID string) error {
	limit, limited := s.orgs[orgID].Plan.SeatLimit()
	if used := s.seatsUsedLocked(orgID); limited && used >= limit {
		return &SeatLimitError{Limit: limit, Used: used}
	}
	return nil
}
EOF
